from flask import Flask, jsonify


SHORT_URLS = {
    "abc123": "https://example.com/articles/intro",
}


def create_app():
    app = Flask(__name__)

    @app.get("/r/<code>")
    def resolve(code):
        try:
            target = SHORT_URLS[code]
        except KeyError:
            return jsonify(error="unknown short code"), 404
        return jsonify(url=target), 200

    return app


app = create_app()

